import React from 'react';
import OwlCarousel from 'react-owl-carousel';
import 'owl.carousel/dist/assets/owl.carousel.css';
import 'owl.carousel/dist/assets/owl.theme.default.css';

const slides = [
  { img: 'banner-01.jpg', cat: 'Toronto, Canada', title: 'Hurry!', text: 'Get the Best Villa for you' },
  { img: 'banner-02.jpg', cat: 'Miami, South Florida', title: 'Act now!', text: 'Get the highest level penthouse' },
  { img: 'banner-03.jpg', cat: 'Sunny Isles Beach', title: 'Be quick!', text: 'Get the best villa in town' },
];

function Banner() {
  return (
    <div className="main-banner">
      <OwlCarousel className="owl-theme main-banner-carousel" loop items={1} nav dots={false} autoplay autoplayTimeout={5000}>
        {slides.map((s) => (
          <div className="item" key={s.img}>
            <div className="header-text" style={{ backgroundImage: `url(/assets/images/${s.img})` }}>
              <span className="category">{s.cat}</span>
              <h2>{s.title}<br />{s.text}</h2>
            </div>
          </div>
        ))}
      </OwlCarousel>
    </div>
  );
}

export default Banner;
