import React, { useContext, useMemo, useState } from 'react';
import AllCompo from '../Components/AllCompo';
import Footer from '../Components/Footer';
import PropertyCard from '../Components/PropertyCard';
import HeaderProp from './HeaderProp';
import { apiValue } from '../Data/AllData';

function AllProp() {
  const { products, loading } = useContext(apiValue);
  const [search, setSearch] = useState('');
  const [cat, setCat] = useState('all');

  const categories = useMemo(() => ['all', ...new Set(products.map((p) => p.category))], [products]);
  const filtered = products.filter(
    (p) => (cat === 'all' || p.category === cat) && p.title.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div>
      <AllCompo />
      <HeaderProp />
      <div className="section properties">
        <div className="container">
          <div className="row mb-4">
            <div className="col-md-6">
              <input className="form-control" placeholder="Search..." value={search} onChange={(e) => setSearch(e.target.value)} />
            </div>
            <div className="col-md-6">
              <select className="form-select" value={cat} onChange={(e) => setCat(e.target.value)}>
                {categories.map((c) => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
          </div>
          <div className="row properties-box">
            {loading && <p className="text-center">Loading...</p>}
            {!loading && filtered.length === 0 && <p className="text-center">No results</p>}
            {filtered.map((p) => <PropertyCard key={p.id} p={p} />)}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default AllProp;
