import React, { useState } from 'react';
import { Link, NavLink } from 'react-router-dom';
import { useCart } from 'react-use-cart';

function Navbar() {
  const [open, setOpen] = useState(false);
  const { totalItems } = useCart();

  return (
    <header className="header-area header-sticky">
      <div className="container">
        <div className="row">
          <div className="col-12">
            <nav className="main-nav">
              <Link to="/" className="logo">
                <h1>Villa</h1>
              </Link>
              <ul className="nav" style={open ? { display: 'block' } : undefined}>
                <li><NavLink to="/" end>Home</NavLink></li>
                <li><NavLink to="/properties">Properties</NavLink></li>
                <li><NavLink to="/details">Property Details</NavLink></li>
                <li><NavLink to="/contact">Contact Us</NavLink></li>
                <li><NavLink to="/cart"><i className="fa fa-shopping-cart" /> Cart ({totalItems})</NavLink></li>
                <li>
                  <Link to="/contact"><i className="fa fa-calendar" /> Schedule a visit</Link>
                </li>
              </ul>
              <a className="menu-trigger" onClick={(e) => { e.preventDefault(); setOpen(!open); }} href="#!">
                <span>Menu</span>
              </a>
            </nav>
          </div>
        </div>
      </div>
    </header>
  );
}

export default Navbar;
