import React, { useContext } from 'react';
import { useParams } from 'react-router-dom';
import { useCart } from 'react-use-cart';
import AllCompo from '../Components/AllCompo';
import Footer from '../Components/Footer';
import { apiValue } from '../Data/AllData';

function AllDetails() {
  const { id } = useParams();
  const { products, loading } = useContext(apiValue);
  const { addItem } = useCart();
  const p = id ? products.find((x) => String(x.id) === id) : products[0];

  return (
    <div>
      <AllCompo />
      <div className="page-heading header-text">
        <div className="container">
          <span className="breadcrumb">Home / Property Details</span>
          <h3>Single Property</h3>
        </div>
      </div>
      <div className="single-property section">
        <div className="container">
          {loading && <p className="text-center">Loading...</p>}
          {!loading && !p && <p className="text-center">Property not found</p>}
          {p && (
            <div className="row">
              <div className="col-lg-8">
                <img src={p.images?.[0] || p.thumbnail} alt={p.title} style={{ width: '100%', borderRadius: 20 }} />
              </div>
              <div className="col-lg-4">
                <span className="category">{p.category}</span>
                <h2>{p.title}</h2>
                <h4>${p.price}</h4>
                <p>{p.description}</p>
                <ul>
                  <li>Brand: {p.brand || 'N/A'}</li>
                  <li>Stock: {p.stock}</li>
                  <li>Rating: {p.rating}</li>
                </ul>
                <button className="btn btn-dark" onClick={() => addItem(p)}>Add to cart</button>
              </div>
            </div>
          )}
        </div>
      </div>
      <Footer />
    </div>
  );
}

export default AllDetails;
