import React from 'react';
import { useCart } from 'react-use-cart';
import { Link } from 'react-router-dom';
import AllCompo from '../Components/AllCompo';
import Footer from '../Components/Footer';

function Cart() {
  const { items, updateItemQuantity, removeItem, totalItems, totalUniqueItems, cartTotal, emptyCart, isEmpty } = useCart();

  if (isEmpty) {
    return (
      <div className="container" style={{ padding: '80px 0', textAlign: 'center' }}>
        <h2>Your cart is empty</h2>
        <Link to="/properties" className="main-button" style={{ display: 'inline-block', marginTop: 20 }}>Browse properties</Link>
      </div>
    );
  }

  return (
    <div className="container" style={{ padding: '60px 0' }}>
      <h3>Cart ({totalUniqueItems} items, {totalItems} units)</h3>
      <table className="table align-middle">
        <thead>
          <tr><th>Image</th><th>Title</th><th>Price</th><th>Quantity</th><th></th></tr>
        </thead>
        <tbody>
          {items.map((item) => (
            <tr key={item.id}>
              <td><img src={item.thumbnail} alt={item.title} width="60" /></td>
              <td>{item.title}</td>
              <td>${item.price}</td>
              <td>
                <button className="btn btn-sm btn-outline-dark" onClick={() => updateItemQuantity(item.id, item.quantity - 1)}>-</button>
                <span style={{ margin: '0 10px' }}>{item.quantity}</span>
                <button className="btn btn-sm btn-outline-dark" onClick={() => updateItemQuantity(item.id, item.quantity + 1)}>+</button>
              </td>
              <td><button className="btn btn-sm btn-danger" onClick={() => removeItem(item.id)}>Remove</button></td>
            </tr>
          ))}
        </tbody>
      </table>
      <h4>Total: ${cartTotal.toFixed(2)}</h4>
      <button className="btn btn-dark" onClick={emptyCart}>Empty cart</button>
    </div>
  );
}

function AllCart() {
  return (
    <div>
      <AllCompo />
      <Cart />
      <Footer />
    </div>
  );
}

export default AllCart;
