import React from 'react';
import { Link } from 'react-router-dom';
import { useCart } from 'react-use-cart';

function PropertyCard({ p }) {
  const { addItem } = useCart();
  return (
    <div className="col-lg-4 col-md-6">
      <div className="item">
        <Link to={`/details/${p.id}`}>
          <img src={p.thumbnail} alt={p.title} style={{ width: '100%', height: 260, objectFit: 'cover' }} />
        </Link>
        <span className="category">{p.category}</span>
        <h6>${p.price}</h6>
        <h4><Link to={`/details/${p.id}`}>{p.title}</Link></h4>
        <ul>
          <li>Brand: <span>{p.brand || 'N/A'}</span></li>
          <li>Stock: <span>{p.stock}</span></li>
          <li>Rating: <span>{p.rating}</span></li>
        </ul>
        <div className="main-button">
          <button type="button" onClick={() => addItem(p)} style={{ border: 0, background: 'transparent', color: 'inherit' }}>
            Add to cart
          </button>
        </div>
      </div>
    </div>
  );
}

export default PropertyCard;
