import React, { useContext, useState } from 'react';
import { apiValue } from '../Data/AllData';

const tabs = ['apartment', 'villa', 'penthouse'];

function BestDeal() {
  const { products } = useContext(apiValue);
  const [tab, setTab] = useState(0);
  const shown = products.slice(tab * 3, tab * 3 + 3);

  return (
    <div className="section best-deal">
      <div className="container">
        <div className="row">
          <div className="col-lg-4">
            <div className="section-heading">
              <h6>| Best Deal</h6>
              <h2>Find Your Best Deal Right Now!</h2>
            </div>
          </div>
        </div>
      </div>
      <div className="container">
        <div className="row">
          <div className="col-lg-12">
            <div className="tabs-content">
              <div className="row">
                <div className="nav-wrapper">
                  <ul className="nav nav-tabs" role="tablist">
                    {tabs.map((t, i) => (
                      <li className="nav-item" key={t}>
                        <button className={`nav-link ${tab === i ? 'active' : ''}`} type="button" onClick={() => setTab(i)}>
                          {t[0].toUpperCase() + t.slice(1)}
                        </button>
                      </li>
                    ))}
                  </ul>
                </div>
                <div className="tab-content">
                  <div className="row">
                    {shown.map((p) => (
                      <div className="col-lg-4" key={p.id}>
                        <img src={p.thumbnail} alt={p.title} style={{ width: '100%' }} />
                        <h4>{p.title}</h4>
                        <p>{p.description}</p>
                        <span className="category">${p.price}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default BestDeal;
