import axios from 'axios';
import React, { createContext, useEffect, useState } from 'react';

const apiValue = createContext({ products: [], loading: true });

function AllData({ children }) {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios
      .get('https://dummyjson.com/products?limit=30')
      .then((res) => setProducts(res.data.products))
      .catch((err) => console.error('API error:', err))
      .finally(() => setLoading(false));
  }, []);

  return <apiValue.Provider value={{ products, loading }}>{children}</apiValue.Provider>;
}

export { AllData, apiValue };
